import * as THREE from 'three';

// PBR texture library. Every map is a seamless tile generated by
// tools/build_textures.py; UVs on world geometry are in meters, so `repeat`
// below is "tiles per meter".

const loader = new THREE.TextureLoader();
const cache = new Map();
let maxAniso = 8;

export function setMaxAnisotropy(n) {
  maxAniso = n;
}

export function tex(name, { srgb = false, repeat = 1 } = {}) {
  const key = `${name}|${srgb}|${repeat}`;
  if (cache.has(key)) return cache.get(key);
  const t = loader.load(import.meta.env.BASE_URL + `textures/${name}.jpg`);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repeat, repeat);
  t.anisotropy = maxAniso;
  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
  cache.set(key, t);
  return t;
}

// Full albedo/normal/roughness set for a surface, tiled `perMeter` times.
export function surface(name, perMeter, extra = {}) {
  return new THREE.MeshStandardMaterial({
    map: tex(`${name}_albedo`, { srgb: true, repeat: perMeter }),
    normalMap: tex(`${name}_normal`, { repeat: perMeter }),
    roughnessMap: tex(`${name}_rough`, { repeat: perMeter }),
    roughness: 1,
    ...extra,
  });
}

// ---- Team kits -----------------------------------------------------------
// Blue side (the user) wears green with dark shorts and gold flags; Red side
// wears red with white shorts and blue flags.
export const KITS = {
  0: { jersey: 0x1f7a3d, trim: 0xf2f2ec, shorts: 0x1a1c20, flags: 0xffc21a, socks: 0xf0efe8 },
  1: { jersey: 0xb3241f, trim: 0xffffff, shorts: 0xeeeeea, flags: 0x2f7bff, socks: 0xf0efe8 },
};

const SKIN_TONES = [0x8d5a3b, 0x6b4129, 0xc68863, 0x4a2c1d, 0xe0ac86, 0xa86d47];

// Fabric: base color + a soft sheen in a lighter tint of the same color, so
// folds catch light at grazing angles without washing the kit out.
function fabric(color, normalName, perMeter, sheen) {
  const sheenColor = new THREE.Color(color).lerp(new THREE.Color(sheen), 0.35);
  return new THREE.MeshPhysicalMaterial({
    color,
    roughness: 0.8,
    normalMap: tex(normalName, { repeat: perMeter }),
    normalScale: new THREE.Vector2(0.6, 0.6),
    sheen: 0.45,
    sheenRoughness: 0.6,
    sheenColor,
  });
}

// One shared material set per team plus one skin material per tone, so
// ten players cost a handful of materials (and shader programs).
const teamSets = new Map();
const skinSets = new Map();

export function teamMaterials(team) {
  if (teamSets.has(team)) return teamSets.get(team);
  const kit = KITS[team];
  const set = {
    Jersey: fabric(kit.jersey, 'fabric_normal', 14, 0xffffff),
    Shorts: fabric(kit.shorts, 'knit_normal', 10, 0x888888),
    Socks: fabric(kit.socks, 'knit_normal', 14, 0xffffff),
    Gloves: new THREE.MeshPhysicalMaterial({
      color: 0x15171b, roughness: 0.45, clearcoat: 0.4, clearcoatRoughness: 0.5,
      normalMap: tex('leather_normal', { repeat: 20 }), normalScale: new THREE.Vector2(0.4, 0.4),
    }),
    Cleats: new THREE.MeshPhysicalMaterial({
      color: 0x111214, roughness: 0.35, clearcoat: 0.7, clearcoatRoughness: 0.25,
    }),
    Belt: new THREE.MeshStandardMaterial({ color: 0x0e0f11, roughness: 0.55 }),
    Flag: new THREE.MeshPhysicalMaterial({
      color: kit.flags, roughness: 0.6, side: THREE.DoubleSide,
      sheen: 1, sheenRoughness: 0.4, sheenColor: new THREE.Color(0xffffff),
    }),
    Hair: new THREE.MeshStandardMaterial({ color: 0x15100c, roughness: 0.62,
      normalMap: tex('knit_normal', { repeat: 40 }), normalScale: new THREE.Vector2(0.5, 0.5) }),
    EyeWhite: new THREE.MeshPhysicalMaterial({ color: 0xd9d4cc, roughness: 0.15, clearcoat: 1 }),
    Eyes: new THREE.MeshPhysicalMaterial({ color: 0x1c120c, roughness: 0.1, clearcoat: 1 }),
  };
  teamSets.set(team, set);
  return set;
}

// Skin: physical material with a warm sheen standing in for subsurface glow.
export function skinMaterial(index) {
  const i = ((index % SKIN_TONES.length) + SKIN_TONES.length) % SKIN_TONES.length;
  if (skinSets.has(i)) return skinSets.get(i);
  const m = new THREE.MeshPhysicalMaterial({
    color: SKIN_TONES[i],
    roughness: 0.52,
    sheen: 0.35,
    sheenRoughness: 0.35,
    sheenColor: new THREE.Color(0xff9a7a),
    normalMap: tex('leather_normal', { repeat: 30 }),
    normalScale: new THREE.Vector2(0.12, 0.12),
  });
  skinSets.set(i, m);
  return m;
}
